// Original session UI. Note events match the live four-bar synthesizer sequence.
export function createSessionScreens({api,arrange,mix,dawTexture,mixerTexture,selected}){
 const W=1280,H=720;arrange.width=mix.width=W;arrange.height=mix.height=H;const a=arrange.getContext('2d'),m=mix.getContext('2d');const busNames=['DRUMS','BASS','MUSIC','FX','ROOM','DELAY'],routes=[0,0,0,1,2,2,2,3],colors=['#8a929b','#8a929b','#8a929b','#b99d73','#759c99','#9aa3bc','#9b8ca7','#848b94'];
 const db=v=>v>0?20*Math.log10(Math.pow(v/100,1.4)):-Infinity,fmt=v=>Number.isFinite(v)?v.toFixed(1):'−∞';
 function label(g,s,x,y,size=13,color='#b8c1c8'){g.fillStyle=color;g.font=`${size}px monospace`;g.fillText(s,x,y)}
 function rect(g,x,y,w,h,c){g.fillStyle=c;g.fillRect(x,y,w,h)}
 function header(g,title){rect(g,0,0,W,H,'#24292e');rect(g,0,0,W,28,'#171c20');label(g,'LF / OPEN SESSION_001',17,19,13,'#d5d7d3');label(g,title,360,19,12);label(g,'104.000 BPM    4/4    A MINOR',833,19,13);rect(g,0,28,W,48,'#343b40');label(g,api.audioState.playing?'▶︎  PLAY':'■  STOP',25,57,16,api.audioState.playing?'#81b7a0':'#c1c6c9');const step=api.audioState.playing?(api.audioState.step+63)%64:0;label(g,`${String(Math.floor(step/16)+1).padStart(2,'0')} | ${Math.floor(step%16/4)+1} | ${String(step%4*240).padStart(3,'0')}`,215,58,21,'#d4dce1');label(g,'LOOP  1.1.000 → 5.1.000',492,54,12);label(g,`${api.audioState.context?Math.round(api.audioState.context.sampleRate/1000)+' kHz':'AUDIO OFF'}  /  POST-FADER`,985,55,12)}
 function meter(g,x,y,w,h,dbValue){rect(g,x,y,w,h,'#10191a');const n=Math.max(0,Math.min(1,(dbValue+60)/60));const grad=g.createLinearGradient(0,y+h,0,y);grad.addColorStop(0,'#608d7e');grad.addColorStop(.72,'#a4ac79');grad.addColorStop(.93,'#c9a05c');grad.addColorStop(1,'#cb5655');g.fillStyle=grad;g.fillRect(x,y+h*(1-n),w,h*n);for(let d=0;d<=60;d+=6)rect(g,x,y+h*d/60,w,1,'#243130');}
 function notes(i,bar){const chord=api.progression[bar],out=[];for(let p=0;p<16;p++){if(i===0&&[0,7,8,14].includes(p))out.push([p,.5,36]);if(i===1&&[4,12].includes(p))out.push([p,.5,38]);if(i===2&&p%2===0)out.push([p+(p%4===2?.111:0),.25,42]);if(i===3&&[0,6,10].includes(p))out.push([p,3.7,chord[0]]);if(i===4&&[0,10].includes(p))chord.slice(1).forEach((n,k)=>out.push([p+k*.083,8.9,n]));if(i===6&&p===0)chord.slice(1,4).forEach((n,k)=>out.push([p+k*.277,18.7,n]));if(i===5||i===7){const n=api.melody[(p+bar*2)%16];if(n!==null)out.push([p+(i===7?1.5:0),i===5?3.8:3.4,n])}}return out}
 function drawArrange(levels){header(a,'EDIT / MIDI ARRANGEMENT');rect(a,0,76,252,613,'#30373c');label(a,'TRACKS / I/O',13,100,13);label(a,'BARS | BEATS',266,99,12);for(let bar=0;bar<4;bar++){const x=258+bar*252;rect(a,x,108,251,24,bar%2?'#3a434a':'#424c53');label(a,String(bar+1),x+6,125,14);for(let k=0;k<16;k++)rect(a,x+k*15.75,132,1,520,k%4===0?'#465058':'#313a40')}
 api.channels.forEach((c,i)=>{const y=138+i*64;rect(a,2,y,247,62,c.id===selected()?'#435057':'#343c42');rect(a,4,y,4,61,colors[i]);label(a,`${String(i+1).padStart(2,'0')}  ${c.name}`,17,y+17,14,'#e0e4df');label(a,`SYNTH → ${busNames[routes[i]]}`,17,y+35,10);label(a,`VOL ${fmt(db(c.value))} dB`,17,y+51,10);for(const [j,name] of ['M','S'].entries()){rect(a,165+j*25,y+7,19,16,(j?c.solo:c.mute)?'#ad864d':'#22292e');label(a,name,170+j*25,y+19,11)}meter(a,228,y+6,7,49,levels.channels[i].peakDb);for(let bar=0;bar<4;bar++){const x=258+bar*252;rect(a,x+2,y+3,248,56,colors[i]);rect(a,x+2,y+3,248,12,'#ffffff25');label(a,`${c.name.toLowerCase()}_${String(bar+1).padStart(2,'0')}  ♫`,x+8,y+13,9,'#1c2830');for(const [p,d,n] of notes(i,bar)){const xx=x+3+p*15.55,ww=Math.min(d*15.55,x+250-xx);if(ww>0)rect(a,xx,y+22+(84-n)%30,Math.max(2,ww),2,'#253139')}if(c.mute)rect(a,x+2,y+3,248,56,'#20283099')}});
 const step=api.audioState.playing?(api.audioState.step+63)%64:0;rect(a,258+step*15.75,108,1.5,547,'#e5ece7');rect(a,0,662,W,58,'#1b2227');label(a,'8 INSTRUMENT TRACKS  /  4 GROUPS  /  2 FX RETURNS',18,685,12);label(a,'4-BAR LOOP  •  ORIGINAL INTERACTIVE SESSION',18,706,11,'#798c94');label(a,'MASTER PEAK  '+fmt(Math.max(...levels.master.map(v=>v.peakDb)))+' dBFS',922,685,12);}
 function drawMix(levels){header(m,'MIX / CONSOLE');const items=[...api.channels.map((c,i)=>({c,name:c.name,value:c.value,level:levels.channels[i],type:'track',i})),...busNames.map((name,i)=>({name,value:api.audioState.engine?.buses[i].value??(i>3?61:100),level:levels.buses[i],type:i>3?'return':'bus',i})),{name:'MASTER',value:100,level:levels.master[0],type:'master'}];items.forEach((o,j)=>{const x=12+j*84,w=79;rect(m,x,89,w,581,'#303a40');rect(m,x,89,w,5,o.type==='track'?colors[o.i]:o.type==='master'?'#ac8462':'#607782');label(m,o.name,x+5,112,10,'#e1e5df');label(m,'INSERTS',x+5,134,8,'#84949e');for(let slot=0;slot<3;slot++){rect(m,x+5,140+slot*20,w-10,17,'#1b252b');label(m,o.type==='track'?['HPF','3-BAND EQ','—'][slot]:o.type==='return'?(slot===0?(o.i===4?'ROOM IR':'DLY 432ms'):'—'):o.type==='master'?(slot===0?'BUS COMP':'—'):'—',x+9,152+slot*20,8)}label(m,'SENDS',x+5,215,8,'#84949e');for(let s=0;s<2;s++){rect(m,x+5,223+s*24,w-10,20,'#202b31');const v=o.c?.[s?'delay':'room']??-60;label(m,o.c?(s?'B DELAY':'A ROOM'):'—',x+8,232+s*24,7);label(m,v<=-60?'OFF':v.toFixed(0)+' dB',x+42,240+s*24,7,'#9fb9b1')}label(m,'OUTPUT',x+5,289,8,'#84949e');label(m,o.c?busNames[routes[o.i]]:o.type==='master'?'OUT 1–2':'MIX BUS',x+5,305,9);rect(m,x+5,315,w-10,19,'#1f292e');label(m,'MANUAL',x+14,328,9);const pan=o.c?.pan??0;label(m,pan===0?'PAN  C':`PAN ${pan<0?'L':'R'}${Math.round(Math.abs(pan)*100)}`,x+11,351,9);rect(m,x+9,359,w-18,2,'#6f7e83');rect(m,x+37+pan*25,355,4,9,'#b3bab7');label(m,`M    S`,x+11,389,11);if(o.c?.mute)rect(m,x+8,376,15,17,'#a6815044');if(o.c?.solo)rect(m,x+46,376,15,17,'#9e985e44');rect(m,x+28,413,4,209,'#11181c');const v=Math.max(0,Math.min(1,(db(o.value)+60)/60));rect(m,x+20,613-v*192,20,10,'#bec6c5');rect(m,x+21,617-v*192,18,1,'#424b4f');for(const [k,tt] of ['0','−12','−24','−36','−48','−60'].entries())label(m,tt,x+1,420+k*39,7,'#809098');meter(m,x+49,410,7,213,o.level.peakDb);if(o.type==='master')meter(m,x+60,410,7,213,levels.master[1].peakDb);label(m,fmt(db(o.value)),x+20,645,10,'#d4d9d6');label(m,'dB',x+52,645,8);});label(m,'POST-FADER PEAK / dBFS     •     VU REFERENCE: −18 dBFS RMS = 0 VU',20,697,12,'#9aacb0')}
 const snapshot=document.createElement('canvas');snapshot.width=W;snapshot.height=H;const sx=snapshot.getContext('2d');
 function macWorkspace(g,title){
  sx.clearRect(0,0,W,H);sx.drawImage(g.canvas,0,0);
  const bg=g.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#273043');bg.addColorStop(.5,'#111b30');bg.addColorStop(1,'#53465a');g.fillStyle=bg;g.fillRect(0,0,W,H);
  rect(g,0,0,W,24,'#111824d9');g.font='14px -apple-system,BlinkMacSystemFont,sans-serif';g.fillStyle='#e7eaf0';g.fillText('',16,17);g.font='600 12px -apple-system,BlinkMacSystemFont,sans-serif';g.fillText('Lotus Session',44,17);g.font='12px -apple-system,BlinkMacSystemFont,sans-serif';g.fillText('File    Edit    Track    Mix    Window    Help',154,17);g.fillText('Wi-Fi   ◉   '+new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),1070,17);
  g.fillStyle='#373e48';g.beginPath();g.roundRect(8,30,W-16,632,9);g.fill();
  ['#ff6059','#ffbd2e','#28c841'].forEach((color,i)=>{g.fillStyle=color;g.beginPath();g.arc(25+i*19,44,5,0,Math.PI*2);g.fill()});g.font='12px -apple-system,BlinkMacSystemFont,sans-serif';g.fillStyle='#c9d0d8';g.textAlign='center';g.fillText(title+' — OPEN SESSION',W/2,48);g.textAlign='left';
  g.save();g.beginPath();g.roundRect(8,57,W-16,605,[0,0,9,9]);g.clip();g.drawImage(snapshot,8,57,W-16,605);g.restore();
  g.fillStyle='#b2bdd02b';g.beginPath();g.roundRect(W/2-142,673,284,42,13);g.fill();
  const icons=[['#50aafa','⌘'],['#326ab4','✧'],['#ee6388','♫'],['#696473','≋'],['#a8acb5','⚙︎'],['#39495a','▤']];
  icons.forEach(([c,label],i)=>{const x=W/2-129+i*44;g.fillStyle=c;g.beginPath();g.roundRect(x,679,31,30,7);g.fill();g.fillStyle='#fff';g.font='23px -apple-system,BlinkMacSystemFont,sans-serif';g.textAlign='center';if(label.startsWith('⚙')){g.save();g.translate(x+15,694);g.strokeStyle='#fff';g.lineWidth=1.6;g.beginPath();g.arc(0,0,6,0,Math.PI*2);g.moveTo(2.2,0);g.arc(0,0,2.2,0,Math.PI*2);for(let k=0;k<8;k++){const q=k*Math.PI/4;g.moveTo(Math.cos(q)*6,Math.sin(q)*6);g.lineTo(Math.cos(q)*9,Math.sin(q)*9)}g.stroke();g.restore()}else g.fillText(label,x+15,703);g.textAlign='left'});
 }
 let lastStamp='';
 function update(now){
  const media=window.lotusStudioMedia;
  const isMedia=media&&media.mode!=='session';
  const stamp=isMedia?media.screenStamp():`session/${now}`;
  if(stamp===lastStamp)return;
  lastStamp=stamp;
  if(isMedia){media.render(a,m);macWorkspace(a,'Music');macWorkspace(m,'Library')}
  else{const levels=api.readMeters(now);drawArrange(levels);drawMix(levels);macWorkspace(a,'Arrangement');macWorkspace(m,'Mixer')}
  // Publish both fully painted screens together; never upload a cleared frame.
  dawTexture.needsUpdate=true;mixerTexture.needsUpdate=true;
 }
 return{update};
}
